function phItems(){
 const keys=[...new Set(pharmacy.moves.filter(m=>m.type==='entrada').map(m=>m.name+'|'+m.unit))];
 return keys.map(key=>{const [name,unit]=key.split('|'),moves=pharmacy.moves.filter(m=>m.name===name&&m.unit===unit),entries=moves.filter(m=>m.type==='entrada'),received=entries.reduce((n,m)=>n+m.qty,0),used=moves.filter(m=>m.type==='saida').reduce((n,m)=>n+m.qty,0),cost=entries.reduce((n,m)=>n+m.qty*m.price,0);return {key,name,unit,received,used,balance:received-used,avg:received?cost/received:0,min:pharmacy.minimums[key]||0}})}
