 document.querySelectorAll('[data-ph-min-save]').forEach(btn=>btn.onclick=()=>{const field=[...document.querySelectorAll('[data-ph-min]')].find(el=>el.dataset.phMin===btn.dataset.phMinSave),v=Number(field.value);if(!field.value.trim()||!Number.isFinite(v)||v<0)return alert('Mínimo inválido.');pharmacy.minimums[btn.dataset.phMinSave]=v;phSave();render()});
