 compra_animais:'<path d="M3 9V5l4 3 3-2h4l3 2 4-3v4l-2 3v5l-3 3H8l-3-3v-5L3 9Z"/><path d="M8 12h.1M16 12h.1M10 16l2 1 2-1"/><circle cx="18" cy="19" r="3"/><path d="M18 17.5v3M16.5 19h3"/>',
